var internalId = 1;
var name = "Engineering Building";
var color = "Red";
var height = 20.5f;
var length = 50.0f;
var width = 30.0f;
var x = 100.0f;
var y = 200.0f;
var z = 0.0f;

var building = new Building(internalId, name, color, height, length, width, x, y, z);

Assert.That(building.InternalId, Is.EqualTo(internalId));
Assert.That(building.Name, Is.EqualTo(name));
Assert.That(building.Color, Is.EqualTo(color));
Assert.That(building.Height, Is.EqualTo(height));
Assert.That(building.Length, Is.EqualTo(length));
Assert.That(building.Width, Is.EqualTo(width));
Assert.That(building.X, Is.EqualTo(x));
Assert.That(building.Y, Is.EqualTo(y));
Assert.That(building.Z, Is.EqualTo(z));

var method = typeof(IBuildingListRepository).GetMethod("GetAllBuildingsAsync");

Assert.That(method, Is.Not.Null);
Assert.That(method.ReturnType, Is.EqualTo(typeof(Task<List<Building>>)));
Assert.That(method.GetParameters(), Is.Empty);

var method = typeof(IBuildingListService).GetMethod("GetAllBuildingsAsync");

Assert.That(method, Is.Not.Null);
Assert.That(method.ReturnType, Is.EqualTo(typeof(Task<List<Building>>)));
Assert.That(method.GetParameters(), Is.Empty);

var mockRepository = new Mock<IBuildingListRepository>();
var expectedBuildings = new List<Building>
{
    new Building(1, "Engineering Building", "Red", 20.5f, 50.0f, 30.0f, 100.0f, 200.0f, 0.0f),
    new Building(2, "Science Building", "Blue", 25.0f, 60.0f, 40.0f, 150.0f, 250.0f, 0.0f)
};
mockRepository.Setup(r => r.GetAllBuildingsAsync()).ReturnsAsync(expectedBuildings);

var service = new BuildingListService(mockRepository.Object);

var result = await service.GetAllBuildingsAsync();

Assert.That(result, Is.EqualTo(expectedBuildings));
Assert.That(result.Count, Is.EqualTo(2));
mockRepository.Verify(r => r.GetAllBuildingsAsync(), Times.Once);

var mockRepository = new Mock<IBuildingListRepository>();
var emptyBuildings = new List<Building>();
mockRepository.Setup(r => r.GetAllBuildingsAsync()).ReturnsAsync(emptyBuildings);

var service = new BuildingListService(mockRepository.Object);

var result = await service.GetAllBuildingsAsync();

Assert.That(result, Is.Not.Null);
Assert.That(result, Is.Empty);
Assert.That(result.Count, Is.EqualTo(0));
mockRepository.Verify(r => r.GetAllBuildingsAsync(), Times.Once);

var mockDbContext = new Mock<UCRDatabaseContext>();
var mockDbSet = new Mock<DbSet<Building>>();

var expectedBuildings = new List<Building>
{
    new Building(1, "Engineering Building", "Red", 20.5f, 50.0f, 30.0f, 100.0f, 200.0f, 0.0f),
    new Building(2, "Science Building", "Blue", 25.0f, 60.0f, 40.0f, 150.0f, 250.0f, 0.0f)
}.AsQueryable();

mockDbSet.As<IQueryable<Building>>().Setup(m => m.Provider).Returns(expectedBuildings.Provider);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.Expression).Returns(expectedBuildings.Expression);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.ElementType).Returns(expectedBuildings.ElementType);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.GetEnumerator()).Returns(expectedBuildings.GetEnumerator());

mockDbContext.Setup(c => c.Buildings).Returns(mockDbSet.Object);

var repository = new SqlBuildingListRepository(mockDbContext.Object);

var result = await repository.GetAllBuildingsAsync();

Assert.That(result, Is.Not.Null);
Assert.That(result.Count, Is.EqualTo(2));
Assert.That(result[0].Name, Is.EqualTo("Engineering Building"));
Assert.That(result[1].Name, Is.EqualTo("Science Building"));

var mockDbContext = new Mock<UCRDatabaseContext>();
var mockDbSet = new Mock<DbSet<Building>>();

var emptyBuildings = new List<Building>().AsQueryable();

mockDbSet.As<IQueryable<Building>>().Setup(m => m.Provider).Returns(emptyBuildings.Provider);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.Expression).Returns(emptyBuildings.Expression);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.ElementType).Returns(emptyBuildings.ElementType);
mockDbSet.As<IQueryable<Building>>().Setup(m => m.GetEnumerator()).Returns(emptyBuildings.GetEnumerator());

mockDbContext.Setup(c => c.Buildings).Returns(mockDbSet.Object);

var repository = new SqlBuildingListRepository(mockDbContext.Object);

var result = await repository.GetAllBuildingsAsync();

Assert.That(result, Is.Not.Null);
Assert.That(result, Is.Empty);
Assert.That(result.Count, Is.EqualTo(0));

var id = 1;
var name = "Engineering Building";

var dto = new BuildingDto(id, name);

Assert.That(dto.Id, Is.EqualTo(id));
Assert.That(dto.Name, Is.EqualTo(name));

var buildings = new List<BuildingDto>
{
    new BuildingDto(1, "Engineering Building"),
    new BuildingDto(2, "Science Building")
};

var response = new GetBuildingListResponse(buildings);

Assert.That(response.Buildings, Is.EqualTo(buildings));
Assert.That(response.Buildings.Count, Is.EqualTo(2));

var mockService = new Mock<IBuildingListService>();
var buildings = new List<Building>
{
    new Building(1, "Engineering Building", "Red", 20.5f, 50.0f, 30.0f, 100.0f, 200.0f, 0.0f),
    new Building(2, "Science Building", "Blue", 25.0f, 60.0f, 40.0f, 150.0f, 250.0f, 0.0f)
};
mockService.Setup(s => s.GetAllBuildingsAsync()).ReturnsAsync(buildings);

var result = await GetBuildingListHandler.HandleAsync(mockService.Object);

Assert.That(result, Is.TypeOf<Ok<GetBuildingListResponse>>());
var okResult = result as Ok<GetBuildingListResponse>;
Assert.That(okResult.Value.Buildings.Count, Is.EqualTo(2));
Assert.That(okResult.Value.Buildings[0].Id, Is.EqualTo(1));
Assert.That(okResult.Value.Buildings[0].Name, Is.EqualTo("Engineering Building"));
Assert.That(okResult.Value.Buildings[1].Id, Is.EqualTo(2));
Assert.That(okResult.Value.Buildings[1].Name, Is.EqualTo("Science Building"));

var mockService = new Mock<IBuildingListService>();
var emptyBuildings = new List<Building>();
mockService.Setup(s => s.GetAllBuildingsAsync()).ReturnsAsync(emptyBuildings);

var result = await GetBuildingListHandler.HandleAsync(mockService.Object);

Assert.That(result, Is.TypeOf<Ok<GetBuildingListResponse>>());
var okResult = result as Ok<GetBuildingListResponse>;
Assert.That(okResult.Value.Buildings, Is.Not.Null);
Assert.That(okResult.Value.Buildings, Is.Empty);
Assert.That(okResult.Value.Buildings.Count, Is.EqualTo(0));
